"""6793: пул руки 2 проти руки 1 з жеребом K-SIL-03 на тілах із роллю зон (O, A, H стенда): речей лише в одному з пулів (слот, назва, ціна), по слотах;
`голова` — речей у перших 10 кожного слота руки 2, яких нема в перших 10 руки 1 (пул O менший за бюджет слота: склад той самий, міняється порядок).
Запуск: cd джерела && python3 проби/рука2_пул_зон.py [теку_джерел_ДО]"""
import pathlib, sys, os, json
sys.path.insert(0, sys.argv[1] if len(sys.argv) > 1 else str(pathlib.Path(__file__).resolve().parent.parent)); os.chdir(sys.path[0])
import bridge as Б, поломки as П, fit as ПС
вх0 = dict(json.load(open('стенд_вх.json')), каталог='каталог_повний.xml', сід=3, сценарій=dict(нагода='побачення', місце='ресторан', година=20, темп_c=5, ошатність=[4, 5]))
ТІЛА = dict(O=dict(плечі=112, груди=114, талія=104, стегна=114, високе_стегно=106), A=dict(плечі=92, груди=90, талія=72, стегна=108, високе_стегно=96),
            H=dict(плечі=98, груди=94, талія=80, стегна=99, високе_стегно=90))
П.жереб = lambda *а, **к: (П.злити([П.ЗА_ІД['K-SIL-03']]), ['K-SIL-03'], {}, dict(дія='pool', чому=None))
ключ = lambda р: (р.get('назва'), р.get('ціна'))
for ім, обх in ТІЛА.items():
    вх = dict(вх0, обхвати=обх); з = json.loads(Б.виклик('запити', json.dumps(вх, ensure_ascii=False))); assert not з.get('помилка'), з
    п1, п2 = (з['пакети'][к]['пул'] for к in '12'); гол = lambda п, с: {ключ(р) for р in (п.get(с) or [])[:10]}
    print(json.dumps(dict(тіло=ім, ярлик=ПС.зони(ПС.тіло(вх['зріст'], обх))['ярлик'], пул_різниця=з['поломка'].get('пул_різниця'), слоти=з['поломка'].get('пул_різниця_слоти'),
                          голова={с: len(гол(п2, с) - гол(п1, с)) for с in п1 if гол(п2, с) - гол(п1, с)}), ensure_ascii=False), flush=True)
